D=Path('dist')
svg='''<svg class="neuron-filter-defs" aria-hidden="true" width="0" height="0" xmlns="http://www.w3.org/2000/svg"><defs><filter id="neuron-outline-light" x="-5%" y="-5%" width="110%" height="110%" color-interpolation-filters="sRGB"><feConvolveMatrix in="SourceAlpha" order="3" kernelMatrix="-1 -1 -1 -1 8 -1 -1 -1 -1" divisor="1" bias="0" result="edges"/><feComponentTransfer in="edges" result="bright-edges"><feFuncA type="linear" slope="5"/></feComponentTransfer><feFlood flood-color="#ddc784" result="ivory"/><feComposite in="ivory" in2="bright-edges" operator="in" result="outline"/><feGaussianBlur in="outline" stdDeviation="1.2" result="halo"/><feMerge><feMergeNode in="halo"/><feMergeNode in="outline"/></feMerge></filter></defs></svg><div class="neuron-outline-shine" aria-hidden="true"><span></span><span></span></div>'''
for p in D.glob('*.html'):
 s=p.read_text().replace('<div class="neuron-backdrop" aria-hidden="true"></div>','<div class="neuron-backdrop" aria-hidden="true"></div>'+svg,1);s=re.sub(r'/style.css\?v=[^" ]+','/style.css?v=outline-shine-9',s);s=re.sub(r'/script.js\?v=[^" ]+','/script.js?v=outline-shine-9',s);p.write_text(s)
p=D/'style.css';s=p.read_text()+'''
/* Reflective light extracted from the illustration's actual edges. */
.neuron-filter-defs{position:absolute;pointer-events:none}.neuron-outline-shine{position:fixed;inset:0;z-index:-1;pointer-events:none;opacity:0;transition:opacity .35s ease;mask-image:linear-gradient(115deg,transparent 0%,rgba(0,0,0,.25) 32%,#000 47%,#000 53%,rgba(0,0,0,.25) 68%,transparent 100%);mask-size:220% 220%;mask-position:var(--shine-position,50%) 50%}.neuron-outline-shine>span{position:absolute;inset:0;background:url('/neuron-background.png') center top/max(1200px,100vw) auto repeat-y;filter:url('#neuron-outline-light')}.neuron-outline-shine>span:first-child{background-position:calc(50% + 85px) top;clip-path:inset(0 50% 0 0)}.neuron-outline-shine>span:last-child{clip-path:inset(0 0 0 50%)}.neurons-scrolling .neuron-outline-shine{opacity:.7}.neurons-scrolling .neuron-backdrop{opacity:.08}.neurons-scrolling .neuron-backdrop::before,.neurons-scrolling .neuron-backdrop::after{filter:none}@media(max-width:720px){.neuron-outline-shine>span{background-size:950px auto}.neuron-outline-shine>span:first-child{background-position:calc(50% + 30px) top}.neurons-scrolling .neuron-outline-shine{opacity:.4}.neurons-scrolling .neuron-backdrop{opacity:.04}}@media(prefers-reduced-motion:reduce){.neuron-outline-shine{display:none}}
''';p.write_text(s)
